BEGIN;
DO $$ BEGIN IF current_user<>'ai_mls_production_migration_operator' THEN RAISE EXCEPTION 'REL002_R3B1_MIGRATION_OPERATOR_REQUIRED'; END IF; IF to_regnamespace('app_connector') IS NOT NULL THEN RAISE EXCEPTION 'REL002_R3B1_CONNECTOR_SCHEMA_ALREADY_EXISTS'; END IF; END $$;
CREATE SCHEMA app_connector AUTHORIZATION ai_mls_production_migration_operator;
COMMENT ON SCHEMA app_connector IS 'REL002-R3B1-CONNECTOR-V1|schema_version=1|contract_fingerprint=connector-v1-11-tables';
CREATE TABLE app_connector.connector_schema(singleton_id integer PRIMARY KEY CHECK(singleton_id=1),schema_version bigint NOT NULL CHECK(schema_version=1),contract_fingerprint text NOT NULL CHECK(contract_fingerprint='connector-v1-11-tables'));
CREATE TABLE app_connector.connector_scopes(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,revision bigint NOT NULL CHECK(revision>=0 AND revision<=9007199254740991),PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id));
CREATE TABLE app_connector.connector_leases(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,lease_id text NOT NULL,owner_id text NOT NULL,acquired_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('ACTIVE','RELEASED','EXPIRED')),version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,lease_id),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id) REFERENCES app_connector.connector_scopes(tenant_id,scope_type,scope_id,source_id,connector_id));
CREATE UNIQUE INDEX connector_active_lease_scope ON app_connector.connector_leases(tenant_id,scope_type,scope_id,source_id,connector_id) WHERE status='ACTIVE';
CREATE TABLE app_connector.connector_invocations(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,invocation_id text NOT NULL,lease_id text NOT NULL,idempotency_key text NOT NULL,input_fingerprint text NOT NULL,raw_state text NOT NULL CHECK(raw_state IN('PREPARED','EXECUTION_STARTED','SUCCEEDED','FAILED','AMBIGUOUS')),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id),UNIQUE(tenant_id,scope_type,scope_id,source_id,connector_id,idempotency_key),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id,lease_id) REFERENCES app_connector.connector_leases(tenant_id,scope_type,scope_id,source_id,connector_id,lease_id));
CREATE TABLE app_connector.connector_idempotency(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,idempotency_key text NOT NULL,invocation_id text NOT NULL,input_fingerprint text NOT NULL,result_id text,payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,idempotency_key),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id) REFERENCES app_connector.connector_invocations(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id));
CREATE TABLE app_connector.connector_results(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,invocation_id text NOT NULL,result_id text NOT NULL UNIQUE,outcome text NOT NULL CHECK(outcome IN('SUCCEEDED','FAILED','UNKNOWN')),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id) REFERENCES app_connector.connector_invocations(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id));
CREATE TABLE app_connector.connector_checkpoints(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id));
CREATE TABLE app_connector.connector_evidence(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,invocation_id text NOT NULL,sequence bigint NOT NULL CHECK(sequence>0 AND sequence<=9007199254740991),kind text NOT NULL CHECK(kind IN('INTENT_PREPARED','EXECUTION_STARTED','RESULT_RECORDED')),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id,sequence),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id) REFERENCES app_connector.connector_invocations(tenant_id,scope_type,scope_id,source_id,connector_id,invocation_id));
CREATE TABLE app_connector.connector_technical_records(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,record_type text NOT NULL CHECK(record_type IN('CONNECTOR_INSTANCE','CAPTURE_BATCH','DELIVERY_ATTEMPT','EXTERNAL_OBSERVATION','HEALTH_SIGNAL')),record_id text NOT NULL,version bigint NOT NULL CHECK(version>0 AND version<=9007199254740991),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,record_type,record_id),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id) REFERENCES app_connector.connector_scopes(tenant_id,scope_type,scope_id,source_id,connector_id));
CREATE TABLE app_connector.connector_technical_idempotency(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,idempotency_key text NOT NULL,input_fingerprint text NOT NULL,payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,idempotency_key),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id) REFERENCES app_connector.connector_scopes(tenant_id,scope_type,scope_id,source_id,connector_id));
CREATE TABLE app_connector.connector_technical_evidence(tenant_id text NOT NULL,scope_type text NOT NULL,scope_id text NOT NULL,source_id text NOT NULL,connector_id text NOT NULL,record_type text NOT NULL,record_id text NOT NULL,sequence bigint NOT NULL CHECK(sequence>0 AND sequence<=9007199254740991),payload_json jsonb NOT NULL,PRIMARY KEY(tenant_id,scope_type,scope_id,source_id,connector_id,record_type,record_id,sequence),FOREIGN KEY(tenant_id,scope_type,scope_id,source_id,connector_id,record_type,record_id) REFERENCES app_connector.connector_technical_records(tenant_id,scope_type,scope_id,source_id,connector_id,record_type,record_id));
CREATE FUNCTION app_connector.reject_append_only_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only' USING ERRCODE='55000'; END $$;
CREATE TRIGGER connector_results_append_only BEFORE UPDATE OR DELETE ON app_connector.connector_results FOR EACH ROW EXECUTE FUNCTION app_connector.reject_append_only_mutation();
CREATE TRIGGER connector_evidence_append_only BEFORE UPDATE OR DELETE ON app_connector.connector_evidence FOR EACH ROW EXECUTE FUNCTION app_connector.reject_append_only_mutation();
CREATE TRIGGER connector_technical_idempotency_append_only BEFORE UPDATE OR DELETE ON app_connector.connector_technical_idempotency FOR EACH ROW EXECUTE FUNCTION app_connector.reject_append_only_mutation();
CREATE TRIGGER connector_technical_evidence_append_only BEFORE UPDATE OR DELETE ON app_connector.connector_technical_evidence FOR EACH ROW EXECUTE FUNCTION app_connector.reject_append_only_mutation();
INSERT INTO app_connector.connector_schema VALUES(1,1,'connector-v1-11-tables');
COMMIT;
